function seoRouteLabel(path){return String(path||"").replace(/^\//,"").split("-").map(x=>x==="edt"?"EDT":x.charAt(0).toLocaleUpperCase("tr-TR")+x.slice(1)).join(" ")}
function seoModulesHtml(items){const groups=["HORECA & İşletme","Ürün & Kategori","İstanbul & Tedarik","EDT Rehberi"],a=Array.isArray(items)&&items.length?items:SEO_ROUTES.map((path,i)=>({path,label:seoRouteLabel(path),group_name:groups[Math.min(3,Math.floor(i/50))],sort_order:i}));const buckets=groups.map(g=>a.filter(x=>String(x.group_name||"")===g));if(buckets.some(x=>!x.length)){for(let i=0;i<4;i++)buckets[i]=a.slice(i*50,(i+1)*50)}return '<section class="section seoGuide seoCompact"><div class="sectionhead"><div><h2>EDT Tedarik Rehberi</h2><p>SEO bağlantıları sayfayı kalabalıklaştırmadan dört açılır modül içinde korunur.</p></div></div><div class="seoModules">'+buckets.map((list,i)=>'<details class="seoModule"><summary>'+groups[i]+' <span>'+list.length+' bağlantı</span></summary><div>'+list.slice(0,50).map(x=>'<a href="'+esc(x.path||"#")+'">'+esc(x.label||seoRouteLabel(x.path))+'</a>').join("")+'</div></details>').join("")+'</div></section>'}

function esc(v){return String(v==null?"":v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function money(v,currency="TRY"){const n=Number(v);if(!Number.isFinite(n)||n<=0)return "Fiyat için teklif alın";try{return new Intl.NumberFormat("tr-TR",{style:"currency",currency}).format(n)}catch{return n.toFixed(2)+" ₺"}}
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-okyanus-commerce":BUILD}})}
function html(body,status=200){return new Response(body,{status,headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store","x-okyanus-commerce":BUILD}})}

