function favoriteRuntimeScript(){return "(function(){const K='oky-favorites-v1';function read(){try{const a=JSON.parse(localStorage.getItem(K)||'[]');return Array.isArray(a)?a.map(String):[]}catch{return[]}}function paint(){const a=new Set(read());document.querySelectorAll('[data-fav]').forEach(b=>{const on=a.has(String(b.dataset.fav||''));b.classList.toggle('on',on);b.textContent=on?'♥':'♡';b.setAttribute('aria-label',on?'Favoriden çıkar':'Favoriye ekle')})}document.addEventListener('click',e=>{const b=e.target.closest('[data-fav]');if(!b)return;e.preventDefault();e.stopPropagation();const id=String(b.dataset.fav||'');if(!id)return;const a=new Set(read());a.has(id)?a.delete(id):a.add(id);localStorage.setItem(K,JSON.stringify([...a]));paint()});document.addEventListener('oky-products-rendered',paint);paint()})();"}
function cartRuntimeScript(){return "(function(){const K='oky-commerce-cart-v2';function read(){try{const a=JSON.parse(localStorage.getItem(K)||'[]');return Array.isArray(a)?a:[]}catch{return[]}}function paint(){const n=read().reduce((t,x)=>t+Math.max(1,Number(x&&x.qty||1)),0);document.querySelectorAll('[data-cart-count]').forEach(el=>el.textContent=String(n))}window.addEventListener('storage',paint);document.addEventListener('oky-cart-change',paint);paint()})();"}

function productVisual(p){const c=String(p.category||"").toLocaleLowerCase("tr-TR"),n=String(p.name||"Ürün");const icon=c.includes("deniz")?"🐟":c.includes("donuk")||c.includes("patates")?"❄":c.includes("et")||c.includes("kanat")?"🥩":c.includes("süt")||c.includes("peynir")||c.includes("şark")?"🧀":c.includes("yağ")?"🫗":c.includes("sos")?"🥫":c.includes("baharat")?"✦":c.includes("bakliyat")||c.includes("kuru")?"🌾":"▣";return `<div class="visualFallback"><b>${icon}</b><span>${esc(n)}</span></div>`}
function card(p){const price=p.salePrice??p.sale_price??p.effectivePrice??p.price??p.list_price??null,old=p.listPrice??p.list_price??null,addId=p.source_product_id||p.id||"",img=p.image?`<img loading="lazy" decoding="async" src="${esc(p.image)}" alt="${esc(p.name||"Ürün")}">`:productVisual(p),min=Math.max(.001,Number(p.min_order_qty||1)),step=Math.max(.001,Number(p.qty_step||1)),isNew=p.new_until&&Date.parse(p.new_until)>Date.now();return `<article class="product" data-product="${esc(p.id||"")}"><button class="fav" type="button" data-fav="${esc(addId)}" aria-label="Favoriye ekle">♡</button><div class="img">${img}</div><div class="badges">${p.discountPercent?`<span class="badge sale">%${esc(p.discountPercent)} İNDİRİM</span>`:""}${Number(p.best_seller)===1?`<span class="badge">ÇOK SATAN</span>`:""}${isNew?`<span class="badge">YENİ</span>`:""}${p.customerPrice?`<span class="badge">FİRMANA ÖZEL</span>`:""}${p.legacy?`<span class="badge legacyBadge">ESKİ KATALOG</span>`:""}</div><h3>${esc(p.name||"Ürün")}</h3><div class="meta">${esc(p.brand||p.category||"Okyanus EDT")}<br>${esc(p.package_text||p.package||p.amount||p.unit||"Teklif isteyin")}</div>${p.description||p.detail?`<div class="desc">${esc(p.description||p.detail)}</div>`:""}<div class="price"><span class="priceLabel">Fiyat</span><strong class="${price==null?"ask":""}">${money(price,p.currency||"TRY")}</strong>${old&&price&&Number(old)>Number(price)?`<del>${money(old,p.currency||"TRY")}</del>`:""}</div><div class="stock">${esc(p.stock_status||p.stockStatus||"Fiyat / stok için teklif alın")}</div><div class="qty"><button type="button" data-minus>-</button><input type="number" min="${min}" step="${step}" value="${min}" aria-label="Miktar"><button type="button" data-plus>+</button></div><button class="add" type="button" data-add="${esc(addId)}">Sepete / Teklife Ekle</button></article>`}

