function commerceCartPage(){
 const body=`<main class="wrap"><section class="page"><a class="homeReturn" href="/urunler">← Ürünlere Dön</a><h1>Sepet / Teklif Listem</h1><p>Ürünleri kontrol edin, miktarları düzenleyin ve tek talepte teklif alın.</p><div id="cartStatus" class="cartNotice">Güncel katalog doğrulanıyor…</div><div id="cr"></div><div id="cartSummary" class="commerceBox" style="margin:12px 0"></div><div class="cartActions"><a href="/urunler">+ Ürün Ekle</a><button id="clearCart" class="danger" type="button">Sepeti Temizle</button></div><form id="qf" class="form"><h2>Teklif Bilgileri</h2><input name="name" autocomplete="name" required placeholder="Ad Soyad"><input name="business" autocomplete="organization" required placeholder="İşletme / Firma"><input name="phone" inputmode="tel" autocomplete="tel" required placeholder="Telefon"><input name="email" type="email" autocomplete="email" required placeholder="E-posta"><textarea name="note" placeholder="Teslimat, marka veya ürün notunuz"></textarea><label><input name="consent" type="checkbox" required style="width:auto"> <a href="/kvkk" target="_blank" rel="noopener">KVKK bilgilendirmesini</a> okudum.</label><button id="qSubmit" type="submit">Teklif Talebini Gönder</button><div id="qr" role="status" aria-live="polite"></div></form></section>${contactStrip()}</main>`;
 const script=`(function(){
 const K='oky-commerce-cart-v2';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=v=>{const n=Number(v);return Number.isFinite(n)&&n>0?new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(n):'Teklif fiyatı'};
 const round=v=>Math.round(Number(v||0)*1000)/1000,stepOf=x=>Math.max(.001,Number(x?.qty_step||1)),minOf=x=>Math.max(.001,Number(x?.min_order_qty||stepOf(x))),qty=(v,x)=>round(Math.min(999,Math.max(minOf(x),Number(v||minOf(x)))));
 function read(){try{const raw=JSON.parse(localStorage.getItem(K)||'[]'),a=Array.isArray(raw)?raw:[],m=new Map();for(const x of a){if(!x||!x.id||!x.name)continue;const id=String(x.id),old=m.get(id);if(old)old.qty=round(qty(old.qty,old)+qty(x.qty,x));else m.set(id,{...x,id,qty:qty(x.qty,x)})}return [...m.values()]}catch{return[]}}
 function write(a){localStorage.setItem(K,JSON.stringify(a));document.dispatchEvent(new Event('oky-cart-change'))}
 function slug(v){return String(v||'').toLocaleLowerCase('tr-TR').normalize('NFKD').replace(/[\\u0300-\\u036f]/g,'').replace(/ı/g,'i').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'')}
 function legacy(x){const pack=[x.amount,x.package].filter(Boolean).join(' • '),raw=Number(x.price??x.unitPrice);return {id:String(x.id||slug(x.name)),source_product_id:String(x.id||''),name:String(x.name||'Ürün'),brand:String(x.brand||''),category:String(x.category||x.masterCategory||'Diğer Ürünler'),package_text:pack,unit:/kg/i.test(pack)?'Kg':/litre|\\bL\\b/i.test(pack)?'Litre':'Adet',price:Number.isFinite(raw)&&raw>0?raw:null,image:x.image||x.image_url||x.imageUrl||'',description:String(x.detail||x.description||''),stock_status:x.stock_status||x.stockStatus||'Fiyat / stok için teklif alın'}}
 let catalog=new Map(),catalogLoaded=false,catalogVerified=false,sending=false;
 function catalogPut(p){for(const key of [p&&p.id,p&&p.source_product_id])if(key)catalog.set(String(key),p)}
 function currentItem(x){const p=catalog.get(String(x.id));if(!p)return {...x,missing:catalogVerified};return {...x,missing:false,name:String(p.name||x.name),unit:String(p.unit||x.unit||'Adet'),price:p.sale_price??p.effectivePrice??p.price??p.list_price??x.price??null,category:String(p.category||x.category||''),package_text:String(p.package_text||p.package||x.package_text||''),image:String(p.image||x.image||''),stock_status:String(p.stock_status||p.stockStatus||''),min_order_qty:Math.max(.001,Number(p.min_order_qty||x.min_order_qty||1)),qty_step:Math.max(.001,Number(p.qty_step||x.qty_step||1))}}
 function reconcile(){const a=read().map(currentItem);write(a);return a}
 function draw(){
   const a=read();
   cr.innerHTML=a.length?a.map((x,i)=>{const unit=Number.isFinite(Number(x.price))?money(x.price):'Teklif fiyatı',line=Number.isFinite(Number(x.price))?money(Number(x.price)*qty(x.qty,x)):'Teklifte netleşir',meta=[x.category,x.package_text].filter(Boolean).join(' • '),img=x.image?'<img src="'+esc(x.image)+'" alt="" style="width:56px;height:56px;object-fit:cover;border-radius:9px;float:left;margin-right:10px">':'';return '<div class="commerceCartRow '+(x.missing?'cartMissing':'')+'"><div>'+img+'<b>'+esc(x.name)+'</b><div class="cartLineMeta">'+esc(meta||x.unit||'')+'</div><div class="cartLinePrice">'+unit+' • Satır: '+line+'</div>'+(x.missing?'<div class="cartLineMeta">Bu ürün güncel katalogda bulunamadı. Silip yeniden ekleyin.</div>':'')+'</div><div class="qty" style="margin:0"><button type="button" data-dec="'+i+'">−</button><input data-q="'+i+'" type="number" min="'+minOf(x)+'" step="'+stepOf(x)+'" max="999" value="'+qty(x.qty,x)+'"><button type="button" data-inc="'+i+'">+</button></div><span class="u">'+esc(x.unit||'Adet')+'</span><button data-rm="'+i+'" type="button" aria-label="Ürünü kaldır">×</button></div>'}).join(''):'<div class="commerceBox"><b>Sepetiniz boş.</b><p><a href="/urunler">Ürün seçmeye başlayın →</a></p></div>';
   const priced=a.filter(x=>Number.isFinite(Number(x.price))&&!x.missing),unpriced=a.filter(x=>!Number.isFinite(Number(x.price))&&!x.missing),missing=a.filter(x=>x.missing),total=priced.reduce((t,x)=>t+Number(x.price)*qty(x.qty,x),0),units=round(a.reduce((t,x)=>t+qty(x.qty,x),0));
   cartSummary.innerHTML=a.length?'<b>Sepet özeti</b><p>'+a.length+' kalem • '+units+' toplam miktar'+(priced.length?' • Fiyatlı ara toplam: '+money(total):'')+(unpriced.length?' • '+unpriced.length+' ürünün fiyatı teklifte netleşecek':'')+(missing.length?' • '+missing.length+' ürün yeniden seçilmeli':'')+'</p>':'<b>Sepet özeti</b><p>Henüz ürün eklenmedi.</p>';
   qSubmit.disabled=sending||!a.length||missing.length>0;
 }
 cr.addEventListener('click',e=>{const a=read();if(e.target.dataset.inc!=null){const i=Number(e.target.dataset.inc);if(a[i])a[i].qty=qty(Number(a[i].qty||minOf(a[i]))+stepOf(a[i]),a[i])}else if(e.target.dataset.dec!=null){const i=Number(e.target.dataset.dec);if(a[i])a[i].qty=qty(Number(a[i].qty||minOf(a[i]))-stepOf(a[i]),a[i])}else if(e.target.dataset.rm!=null){a.splice(Number(e.target.dataset.rm),1)}else return;write(a);draw()});
 cr.addEventListener('change',e=>{if(e.target.dataset.q==null)return;const a=read(),i=Number(e.target.dataset.q);if(!a[i])return;a[i].qty=qty(e.target.value,a[i]);write(a);draw()});
 clearCart.onclick=()=>{if(!read().length)return;if(confirm('Sepetteki tüm ürünler silinsin mi?')){write([]);draw();qr.textContent=''}};
 async function loadCatalog(){
   try{
     const [j,l]=await Promise.all([fetch('/api/storefront-v2',{headers:{accept:'application/json'},cache:'no-store'}).then(r=>r.json()).catch(()=>({products:[]})),fetch('/api/products',{headers:{accept:'application/json'},cache:'no-store'}).then(r=>r.json()).catch(()=>({products:[]}))]);
     const managed=Array.isArray(j.products)?j.products:[],old=Array.isArray(l.products)?l.products.map(legacy):[];
     [...managed,...old].forEach(catalogPut);catalogLoaded=managed.length+old.length>0;catalogVerified=catalogLoaded;
     if(catalogVerified){reconcile();cartStatus.className='cartNotice ok';cartStatus.textContent='Sepet güncel katalog, fiyat ve ürün bilgileriyle doğrulandı.'}
     else{cartStatus.className='cartNotice warn';cartStatus.textContent='Güncel katalog doğrulanamadı. Sepetteki kayıtlı ürün bilgileriyle devam edebilirsiniz.'}
   }catch(_){cartStatus.className='cartNotice warn';cartStatus.textContent='Katalog bağlantısı doğrulanamadı. Sepetteki kayıtlı ürün bilgileri korunuyor.'}
   draw();
 }
 qf.onsubmit=async e=>{
   e.preventDefault();const a=read();if(!a.length){qr.textContent='Önce ürün ekleyin.';return}if(a.some(x=>x.missing)){qr.textContent='Katalogda bulunamayan ürünü silip yeniden ekleyin.';return}
   const f=Object.fromEntries(new FormData(qf)),digits=String(f.phone||'').replace(/\\D/g,'');if(digits.length<10){qr.textContent='Telefon numarasını kontrol edin.';return}
   const payload={customer:{name:String(f.name||'').trim(),business:String(f.business||'').trim(),phone:String(f.phone||'').trim(),email:String(f.email||'').trim()},products:a.map(x=>({id:String(x.id),name:String(x.name),quantity:qty(x.qty,x),unit:String(x.unit||'Adet')})),note:String(f.note||'').trim(),consent:{kvkk:true,textVersion:'2026-09-30-commerce-v2-cart'}};
   sending=true;draw();qr.textContent='Teklif talebiniz gönderiliyor…';
   try{const r=await fetch('/api/quote',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});let j={};try{j=await r.json()}catch{}if(!r.ok){qr.textContent=j.message||j.error||'Teklif gönderilemedi. Bilgileri kontrol edip tekrar deneyin.';return}const no=j.quoteNo||j.requestNo||j.inquiryNo||j.id||'';write([]);qf.reset();draw();qr.innerHTML='<div class="cartConfirm">Teklif talebiniz alındı'+(no?' • Talep No: '+esc(no):'')+'. Satış ekibimiz sizinle iletişime geçecek.</div>'}catch(_){qr.textContent='Bağlantı hatası. Sepetiniz korunuyor; tekrar deneyebilirsiniz.'}finally{sending=false;draw()}
 };
 draw();loadCatalog();
 })();`;
 return html(commerceClientShell('Sepet / Teklif | Okyanus EDT',body,script));
}
function commerceProductPage(slugValue){
 const body='<main class="wrap"><section class="page" id="pd"><h1>Ürün yükleniyor…</h1></section><section class="section"><h2>Benzer Ürünler</h2><div id="rel" class="commerceGrid"></div></section>'+contactStrip()+'</main>';
 const script="(function(){const target="+JSON.stringify(slugValue)+",K='oky-commerce-cart-v2';const slug=v=>String(v||'').toLocaleLowerCase('tr-TR').normalize('NFKD').replace(/[\\u0300-\\u036f]/g,'').replace(/ı/g,'i').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');const esc=v=>String(v??'').replace(/[&<>]/g,'');const money=v=>{const n=Number(v);return Number.isFinite(n)&&n>0?new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(n):'Fiyat için teklif alın'};const norm=x=>({id:String(x.id||slug(x.name)),source_product_id:String(x.id||''),name:String(x.name||'Ürün'),brand:String(x.brand||''),category:String(x.category||x.masterCategory||'Diğer Ürünler'),package_text:[x.amount,x.package].filter(Boolean).join(' • '),unit:/kg/i.test(String(x.amount||''))?'Kg':'Adet',stock_status:'Fiyat / stok için teklif alın',legacy:true});Promise.all([fetch('/api/storefront-v2',{headers:{accept:'application/json'},cache:'no-store'}).then(r=>r.json()).catch(()=>({products:[]})),fetch('/api/products',{headers:{accept:'application/json'},cache:'no-store'}).then(r=>r.json()).catch(()=>({products:[]}))]).then(([j,l])=>{const managed=Array.isArray(j.products)?j.products:[],legacy=(Array.isArray(l.products)?l.products:[]).map(norm),a=[...managed,...legacy.filter(x=>!managed.some(m=>String(m.source_product_id||m.id)===String(x.source_product_id||x.id)))],p=a.find(x=>slug(x.name)===target||String(x.id)===target||String(x.source_product_id)===target);if(!p){pd.innerHTML='<h1>Ürün bulunamadı</h1><a href=\\\"/urunler\\\">Kataloğa dön</a>';return}const price=p.sale_price??p.effectivePrice??p.price??p.list_price??null,old=p.list_price??p.listPrice??null,min=Math.max(.001,Number(p.min_order_qty||1)),step=Math.max(.001,Number(p.qty_step||1)),img=p.image?'<img src=\\\"'+String(p.image).replace(/[\\\"'<>]/g,'')+'\\\" alt=\\\"'+esc(p.name)+'\\\">':'<div class=\\\"visualFallback\\\"><b>▣</b><span>'+esc(p.name)+'</span></div>',stock=esc(p.stock_status||p.stockStatus||'Fiyat / stok için teklif alın');document.title=esc(p.seo_title||p.name||'Ürün')+' | Okyanus EDT';var md=document.querySelector('meta[name=\\\"description\\\"]');if(!md){md=document.createElement('meta');md.name='description';document.head.appendChild(md)}md.content=esc(p.seo_description||p.description||p.category||'Okyanus EDT profesyonel ürün kataloğu');pd.innerHTML='<div class=\\\"detail\\\"><div class=\\\"img\\\">'+img+'</div><div><button class=\\\"fav\\\" type=\\\"button\\\" data-fav=\\\"'+esc(String(p.source_product_id||p.id||''))+'\\\" aria-label=\\\"Favoriye ekle\\\">♡</button><a href=\\\"/\\\" class=\\\"homeReturn\\\">← Ana Sayfa</a><h1>'+esc(p.name)+'</h1><p>'+esc(p.brand||p.category||'')+'</p><p>'+esc(p.package||p.package_text||p.unit||'')+'</p>'+(p.sku?'<p><b>SKU:</b> '+esc(p.sku)+'</p>':'')+(p.subcategory?'<p><b>Alt kategori:</b> '+esc(p.subcategory)+'</p>':'')+(p.origin?'<p><b>Menşei:</b> '+esc(p.origin)+'</p>':'')+(p.storage_conditions?'<p><b>Saklama:</b> '+esc(p.storage_conditions)+'</p>':'')+(Number(p.cold_chain)===1?'<p><b>Soğuk zincir gerektirir.</b></p>':'')+(p.description?'<p>'+esc(p.description)+'</p>':'')+'<div class=\\\"price\\\"><span class=\\\"priceLabel\\\">Fiyat</span><strong>'+money(price)+'</strong>'+(old&&price&&Number(old)>Number(price)?'<del>'+money(old)+'</del>':'')+'</div><div class=\\\"stock\\\">'+stock+'</div><p><small>Minimum: '+min+' • Adım: '+step+' '+esc(p.unit||'Adet')+'</small></p><div class=\\\"qty\\\" style=\\\"max-width:190px;margin:14px 0\\\"><button type=\\\"button\\\" id=\\\"pdMinus\\\">-</button><input id=\\\"pdQty\\\" type=\\\"number\\\" min=\\\"'+min+'\\\" step=\\\"'+step+'\\\" value=\\\"'+min+'\\\"><button type=\\\"button\\\" id=\\\"pdPlus\\\">+</button></div><button class=\\\"btn\\\" style=\\\"background:#0768b2;color:#fff;border:0\\\" id=\\\"pdAdd\\\">Sepete / Teklife Ekle</button><p><a href=\\\"/iletisim\\\">Bu ürün hakkında satış ekibine sor →</a></p></div></div>';const q=document.getElementById('pdQty');const round=v=>Math.round(v*1000)/1000;document.getElementById('pdPlus').onclick=()=>q.value=round(Math.min(999,Math.max(min,Number(q.value||min)+step)));document.getElementById('pdMinus').onclick=()=>q.value=round(Math.max(min,Number(q.value||min)-step));document.getElementById('pdAdd').onclick=()=>{let cart=[];try{cart=JSON.parse(localStorage.getItem(K)||'[]')}catch{}const id=String(p.source_product_id||p.id||'');if(!id){document.getElementById('pdAdd').textContent='Ürün kodu eksik';return}const qty=round(Math.min(999,Math.max(min,Number(q.value||min)))),x=cart.find(v=>String(v.id)===id),price=p.sale_price??p.effectivePrice??p.price??p.list_price??null,stock=String(p.stock_status||p.stockStatus||'');if(/stok yok|tükendi|pasif|inactive|out of stock/i.test(stock)){document.getElementById('pdAdd').textContent='Stokta yok';return}const pack=String(p.package_text||p.package||''),category=String(p.category||''),image=String(p.image||''),unit=String(p.unit||'Adet');if(x){x.qty=round(Math.min(999,Math.max(min,Number(x.qty||min)+qty)));x.name=p.name;x.unit=unit;x.price=price;x.package_text=pack;x.category=category;x.image=image;x.min_order_qty=min;x.qty_step=step}else cart.push({id,name:p.name,unit,qty,price,package_text:pack,category,image,min_order_qty:min,qty_step:step});localStorage.setItem(K,JSON.stringify(cart));document.dispatchEvent(new Event('oky-cart-change'));document.getElementById('pdAdd').textContent='Sepete Eklendi ✓'};rel.innerHTML=a.filter(x=>x!==p&&x.category===p.category).slice(0,5).map(x=>'<div class=\\\"commerceBox\\\"><b>'+esc(x.name)+'</b><p>'+esc(x.category||'')+'</p><p>'+money(x.sale_price??x.effectivePrice??x.price??x.list_price??null)+'</p><a href=\\\"/urun/'+slug(x.name)+'\\\">İncele →</a></div>').join('')}).catch(()=>pd.innerHTML='<h1>Ürün yüklenemedi.</h1>')})();";
 return html(commerceClientShell('Ürün | Okyanus EDT',body,script));
}
function commerceBrandsPage(){
 const body='<main class="wrap"><section class="page"><h1>Markalar</h1><p>Profesyonel mutfak ürünlerini markaya göre keşfedin.</p><div id="brands" class="helpgrid"><div class="help"><b>Markalar yükleniyor…</b></div></div></section></main>';
 const script="fetch('/api/storefront-v2',{headers:{accept:'application/json'},cache:'no-store'}).then(r=>r.json()).then(j=>{const a=Array.isArray(j.brands)?j.brands:[];brands.innerHTML=a.length?a.map(x=>'<a class=\\\"help\\\" href=\\\"/urunler?q='+encodeURIComponent(x.name||'')+'\\\"><b>'+String(x.name||'').replace(/[&<>]/g,'')+'</b><span>'+String(x.description||'Ürünleri görüntüle').replace(/[&<>]/g,'')+'</span></a>').join(''):'<div class=\\\"help\\\"><b>Markalar</b><span>Aktif marka kaydı bulunmuyor.</span></div>'}).catch(()=>brands.innerHTML='<div class=\\\"help\\\">Markalar yüklenemedi.</div>')";
 return html(commerceClientShell('Markalar | Okyanus EDT',body,script));
}
function commerceCampaignsPage(){
 const body='<main class="wrap"><section class="page"><h1>Kampanyalar</h1><p>Aktif ürün, sepet, hediye ve teslimat kampanyaları burada yayınlanır.</p><div id="campaignList" class="helpgrid"><div class="help"><b>Kampanyalar yükleniyor…</b></div></div></section></main>';
 const script="fetch('/api/storefront-v2',{headers:{accept:'application/json'},cache:'no-store'}).then(r=>r.json()).then(j=>{const a=Array.isArray(j.campaigns)?j.campaigns:[];campaignList.innerHTML=a.length?a.map(x=>{const t=String(x.title||'Kampanya').replace(/[&<>]/g,''),d=String(x.description||'').replace(/[&<>]/g,''),u=String(x.cta_url||'/urunler').replace(/[\\\"'<>]/g,''),c=String(x.cta_text||'İncele').replace(/[&<>]/g,'');return '<article class=\\\"help\\\"><b>'+t+'</b><span>'+d+'</span><a href=\\\"'+u+'\\\">'+c+' →</a></article>'}).join(''):'<div class=\\\"help\\\"><b>Aktif kampanya yok</b><span>Yeni kampanyalar yönetim panelinden yayınlandığında burada görünür.</span></div>'}).catch(()=>campaignList.innerHTML='<div class=\\\"help\\\">Kampanyalar yüklenemedi.</div>')";
 return html(commerceClientShell('Kampanyalar | Okyanus EDT',body,script));
}
function commerceDeliveryPage(){
 const body='<main class="wrap"><section class="page"><h1>Teslimat</h1><p>İlçe, minimum sipariş, teslimat ücreti ve soğuk zincir kuralları teklif/sipariş aşamasında doğrulanır.</p><div id="deliveryList" class="helpgrid"><div class="help"><b>Teslimat kuralları yükleniyor…</b></div></div><p><a class="btn" style="background:#0768b2;color:#fff" href="/iletisim">Teslimat Hakkında Sor</a></p></section></main>';
 const script="fetch('/api/storefront-v2',{headers:{accept:'application/json'},cache:'no-store'}).then(r=>r.json()).then(j=>{const a=Array.isArray(j.delivery)?j.delivery:[];deliveryList.innerHTML=a.length?a.map(x=>{const title=[x.region,x.district].filter(Boolean).join(' • '),parts=[];if(Number(x.min_order)>0)parts.push('Minimum sipariş: '+Number(x.min_order).toLocaleString('tr-TR')+' ₺');if(Number(x.fee)>0)parts.push('Teslimat: '+Number(x.fee).toLocaleString('tr-TR')+' ₺');if(Number(x.free_threshold)>0)parts.push('Ücretsiz limit: '+Number(x.free_threshold).toLocaleString('tr-TR')+' ₺');if(x.delivery_days)parts.push(String(x.delivery_days));if(Number(x.cold_chain)!==0)parts.push('Soğuk zincir');return '<article class=\\\"help\\\"><b>'+String(title||'Teslimat').replace(/[&<>]/g,'')+'</b><span>'+parts.join(' • ').replace(/[&<>]/g,'')+'</span></article>'}).join(''):'<div class=\\\"help\\\"><b>Teslimat bilgisi</b><span>İlçe bazlı kurallar yönetim panelinden yayınlandığında burada görünür.</span></div>'}).catch(()=>deliveryList.innerHTML='<div class=\\\"help\\\">Teslimat bilgileri yüklenemedi.</div>')";
 return html(commerceClientShell('Teslimat | Okyanus EDT',body,script));
}

async function adminPanelRedirect(env){
 let target=String(env?.ADMIN_PANEL_URL||env?.OKYANUS_ADMIN_URL||DEFAULT_SETTINGS.adminUrl||"").trim();
 target=target.replace("https://okyonus-edt-admin.hasan-kaya474.workers.dev","https://okyanus-edt-admin.hasan-kaya474.workers.dev");
 try{const DB=env&&(env.DB||env.ADMIN_DB||env["Veritabanı"]||env["Veritabani"]||env["Veritabanı1"]);if(DB){const has=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_storefront_settings_v1'").first();if(has){const row=await DB.prepare("SELECT value FROM oky_storefront_settings_v1 WHERE key='adminUrl' LIMIT 1").first();if(row?.value)target=String(row.value).trim()}}}catch(_){}
 if(!/^https:\/\//i.test(target))return html('<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Yönetici | Okyanus EDT</title><body style="font-family:Arial;padding:30px"><h1>Yönetici paneli bağlantısı tanımlı değil.</h1><p>ZAMAN/Admin Worker tarafındaki <b>/commerce</b> panelini kullanın.</p><p><a href="/">← Ana Sayfa</a></p></body></html>',503);
 return Response.redirect(target,302);
}

export async function commerceRoute(request,env){
 const u=new URL(request.url),p=u.pathname.length>1&&u.pathname.endsWith("/")?u.pathname.slice(0,-1):u.pathname,m=request.method;
 if(!["GET","HEAD"].includes(m)&&p!=="/api/storefront-v2"&&p!=="/api/newsletter")return null;
 if((m==="GET"||m==="HEAD")&&p==="/")return html(home());
 if((m==="GET"||m==="HEAD")&&p==="/yonetici")return await adminPanelRedirect(env);
 if((m==="GET"||m==="HEAD")&&(p==="/yardim"||p==="/site-yardim"))return html(help());
 if((m==="GET"||m==="HEAD")&&p==="/iletisim")return html(contact());
 if((m==="GET"||m==="HEAD")&&p==="/icerik-studyo")return html(studio());
 if((m==="GET"||m==="HEAD")&&p==="/urunler")return commerceCatalogPage();
 if((m==="GET"||m==="HEAD")&&p==="/sepet")return commerceCartPage();
 if((m==="GET"||m==="HEAD")&&p.startsWith("/urun/"))return commerceProductPage(decodeURIComponent(p.slice(6)));
 if((m==="GET"||m==="HEAD")&&p==="/markalar")return commerceBrandsPage();
 if((m==="GET"||m==="HEAD")&&p==="/kampanyalar")return commerceCampaignsPage();
 if((m==="GET"||m==="HEAD")&&p==="/teslimat")return commerceDeliveryPage();
 if(m==="GET"&&p==="/api/storefront-v2")return storefront(env);
 if(m==="POST"&&p==="/api/newsletter")return newsletterApi(request,env);
 return null;
}

export const OKY_COMMERCE_V2_BUILD=BUILD;
